int main() {
    int s, t, a, b;
    cin >> s>>t>>a>>b;
    int diff = max(s, t) - min(s, t);
    if (diff == 0 || diff % b == 0) {
        cout << 0;
        return 0;
    }
    // diff = ax + by 枚举两种情况 x 为整数和负数的情况
    int res = 1;
    while ((diff - res * a) % b != 0 && (diff + res * a) % b != 0) {
        res++;
    }
​
    cout << res;
    return 0;
}

