const readline = require("readline");
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
rl.on("line", (input) => {
    let [s, t, a, b] = input.split(" ").map(Number);
    let diff = Math.abs(s - t);
​
    if (diff === 0 || diff % b === 0) {
        console.log(0);
        rl.close();
        return;
    }
​
    let res = 1;
    while ((diff - res * a) % b !== 0 && (diff + res * a) % b !== 0) {
        res++;
    }
​
    console.log(res);
    rl.close();
});
