func minAUsage(s, t, a, b int) int {
    diff := abs(s - t)
    if diff == 0 || diff%b == 0 {
        return 0
    }
​
    res := 1
    for (diff-res*a)%b != 0 && (diff+res*a)%b != 0 {
        res++
    }
​
    return res
}
​
func abs(x int) int {
    if x < 0 {
        return -x
    }
    return x
}
​
func main() {
    var s, t, a, b int
    fmt.Scan(&s, &t, &a, &b)
